"""Regenera las cuatro páginas estáticas, sin dependencias externas."""
from pathlib import Path

ROOT = Path(__file__).resolve().parent
products = [
    ('Americano', 'Intenso, aromático y sin prisas. La esencia del café en cada sorbo.', 'popular-1.jpg', 'clasicos'),
    ('Cappuccino', 'Espresso y leche aterciopelada. Un equilibrio que siempre apetece.', 'popular-2.jpg', 'con-leche'),
    ('Mocha', 'El encuentro del café con el chocolate, con un final suave y cremoso.', 'popular-3.jpg', 'con-leche'),
]

def cards():
    return '<div class="cards">' + ''.join(f'''<article class="coffee-card reveal" data-category="{cat}">
      <a class="card-photo" href="contact.html?producto={name}"><img src="img/{img}" alt="Café {name.lower()} servido en taza" width="286" height="166" loading="lazy"><span>Ver detalles ↗</span></a>
      <div class="card-copy"><span class="eyebrow">{'EL CLÁSICO' if cat == 'clasicos' else 'SUAVE Y CREMOSO'}</span><h3>{name}</h3><p>{desc}</p><a class="text-link" href="contact.html?producto={name}">Consultar disponibilidad <span aria-hidden="true">↗</span></a></div>
    </article>''' for name, desc, img, cat in products) + '</div>'

def page(filename, title, content):
    links = [('index.html','Inicio'), ('menu.html','Nuestra carta'), ('today-special.html','Especiales'), ('index.html#historia','Nuestra esencia')]
    nav = ''.join(f'<a href="{url}"'+ (' aria-current="page"' if filename == url else '') + f'>{label}</a>' for url,label in links)
    html = f'''<!DOCTYPE html>
<html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<meta name="description" content="Cafe House: descubre nuestros cafés, encuentra tu favorito y disfruta de una pausa hecha a tu medida."><meta name="theme-color" content="#243c32">
<title>{title} | Cafe House</title><link rel="icon" href="img/favicon.ico"><link rel="stylesheet" href="css/cafe-house.css"><script src="js/cafe-house.js" defer></script></head>
<body><a class="skip-link" href="#main">Saltar al contenido</a>
<header class="site-header"><div class="container header-inner"><a class="brand" href="index.html" aria-label="Cafe House, inicio"><img src="img/logo.png" width="32" height="41" alt=""><span>Cafe House<small>CAFÉ · CON CALMA</small></span></a><button class="menu-toggle" type="button" aria-expanded="false" aria-controls="navigation">Menú <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Navegación principal">{nav}<a class="nav-contact" href="contact.html" {'aria-current="page"' if filename == 'contact.html' else ''}>Hablemos <span aria-hidden="true">↗</span></a></nav></div></header>
<main id="main">{content}</main>
<footer><div class="container footer-top"><div><a class="brand" href="index.html">Cafe House</a><p>Buen café. Buena compañía.<br>Un momento para ti.</p></div><nav aria-label="Navegación del pie"><a href="menu.html">Nuestra carta</a><a href="today-special.html">Especiales</a><a href="contact.html">Contacto</a></nav><p class="footer-note">Tómate la vida<br><em>una taza a la vez.</em></p></div><div class="container footer-bottom"><span>© <span data-year>2026</span> Cafe House</span><span>Diseño original: TemplateMo · Una nueva forma de disfrutarlo</span><a href="#main">Volver arriba ↑</a></div></footer>
</body></html>'''
    (ROOT / filename).write_text(html, encoding='utf-8')

page('index.html', 'Tu pausa favorita', '''
<section class="hero"><div class="container hero-grid"><div class="hero-copy"><p class="eyebrow"><span class="little-line"></span> EL PLACER DE UN BUEN CAFÉ</p><h1>La vida sabe mejor<br>con <em>buen café.</em></h1><p class="hero-description">Baja el ritmo. Disfruta el aroma. Encuentra en cada taza ese pequeño momento que hace especial tu día.</p><div class="hero-actions"><a class="button" href="menu.html">Explorar la carta <span aria-hidden="true">↗</span></a><a class="quiet-link" href="#historia">Conoce nuestra esencia <span aria-hidden="true">↓</span></a></div><div class="hero-signature"><span class="seal" aria-hidden="true">CH</span><p>Hecho para disfrutarse.<br><strong>Sin prisa, con mucho café.</strong></p></div></div><div class="hero-art"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="art-label">EL RITUAL DE CADA DÍA</span><img class="table-image" src="img/table-set.png" width="989" height="523" alt="Barra de cafetería con bancos y equipo para preparar café" fetchpriority="high"><div class="floating-note"><span aria-hidden="true">✦</span><div>Tu momento favorito<small>Empieza con una buena taza.</small></div></div><span class="art-caption">CAFÉ & COMPAÑÍA — LA COMBINACIÓN PERFECTA</span></div></div><a class="scroll-hint" href="#favoritos">DESCUBRE TU PRÓXIMO FAVORITO <span aria-hidden="true">↓</span></a></section>
<div class="values-strip"><div class="container"><span>Una taza, mil momentos</span><i aria-hidden="true">✦</i><span>Preparado con cuidado</span><i aria-hidden="true">✦</i><span>El gusto de hacer una pausa</span><i aria-hidden="true">✦</i><span>Siempre en buena compañía</span></div></div>
<section class="section container" id="favoritos"><div class="section-heading reveal"><div><p class="eyebrow">LOS QUE SIEMPRE APETECEN</p><h2>Encuentra tu <em>favorito.</em></h2></div><a class="text-link" href="menu.html">Ver toda la carta ↗</a></div>''' + cards() + '''</section>
<section class="story section container" id="historia"><div class="story-photo reveal"><img src="img/special-1.jpg" width="520" height="400" alt="Selección de café y acompañamientos de Cafe House" loading="lazy"><span class="photo-tag">Pequeños placeres.<br><em>Grandes momentos.</em></span></div><div class="story-copy reveal"><p class="eyebrow">NUESTRA ESENCIA</p><h2>Mucho más<br>que una <em>taza de café.</em></h2><p>Creemos en las conversaciones que se alargan, en las ideas que nacen entre sorbos y en el placer de dedicarte un momento.</p><p>Por eso, nuestra propuesta es sencilla: tus cafés favoritos, algo rico para acompañar y una invitación a disfrutar sin mirar el reloj.</p><a class="text-link" href="today-special.html">Descubre nuestras combinaciones ↗</a></div></section>
<section class="container"><div class="invitation reveal"><div><p class="eyebrow">HAZLE ESPACIO A UNA PAUSA</p><h2>Tu próxima buena idea<br>empieza con un <em>café.</em></h2></div><a class="button button-cream" href="menu.html">Encuentra el tuyo ↗</a></div></section>''')

page('menu.html', 'Nuestra carta', '''<section class="page-intro container"><p class="eyebrow">A TU GUSTO, A TU RITMO</p><h1>Una taza para<br>cada <em>momento.</em></h1><p>Del primer sorbo intenso al último toque de leche. Encuentra tu forma de disfrutar el café.</p></section><section class="container section menu-section" aria-label="Carta de cafés"><div class="filter-bar" hidden><div class="filters" role="group" aria-label="Filtrar cafés"><button type="button" data-filter="todos" aria-pressed="true">Todos</button><button type="button" data-filter="clasicos" aria-pressed="false">Clásicos</button><button type="button" data-filter="con-leche" aria-pressed="false">Con leche</button></div><p id="filter-status" role="status">3 cafés para descubrir</p></div>''' + cards() + '''<p class="availability">Consulta precios, ingredientes y disponibilidad antes de realizar un pedido.</p></section>''')

page('today-special.html', 'Especiales', '''<section class="page-intro container"><p class="eyebrow">MEJOR EN BUENA COMPAÑÍA</p><h1>Pequeños antojos.<br><em>Grandes combinaciones.</em></h1><p>Ideas para acompañar tu pausa y darle otro sabor a tu día.</p></section><section class="container section specials-grid"><article class="special-card reveal"><img src="img/special-1.jpg" width="520" height="400" alt="Café acompañado de un pequeño bocado" loading="lazy"><div><p class="eyebrow">LA PAUSA COMPLETA</p><h2>Café y algo más.</h2><p>Encuentra el acompañamiento de tu bebida favorita. Consulta las opciones disponibles.</p><a class="text-link" href="contact.html?producto=Caf%C3%A9%20y%20acompa%C3%B1amiento">Consultar opciones ↗</a></div></article><article class="special-card reveal"><img src="img/special-2.jpg" width="360" height="207" alt="Selección de bocados para acompañar el café" loading="lazy"><div><p class="eyebrow">PARA COMPARTIR</p><h2>Una mesa, dos cafés.</h2><p>Una invitación para ponerse al día y disfrutar juntos. Pregunta por nuestras combinaciones.</p><a class="text-link" href="contact.html?producto=Combinaci%C3%B3n%20para%20compartir">Preparar consulta ↗</a></div></article></section>''')

page('contact.html', 'Hablemos', '''<section class="page-intro container"><p class="eyebrow">ESTAMOS PARA ESCUCHARTE</p><h1>Todo empieza con<br>una <em>buena conversación.</em></h1><p>¿Un café en mente? Prepara tu consulta con los detalles que quieras compartir.</p></section><section class="container contact-grid section"><aside class="contact-aside"><span class="eyebrow">TU CONSULTA, A TU MEDIDA</span><h2>Cuéntanos<br>qué se te <em>antoja.</em></h2><p>Puedes preguntar por bebidas, ingredientes o combinaciones.</p><div class="notice"><strong>Antes de empezar</strong><p>El envío en línea aún no está disponible. Este formulario genera un archivo de texto para que conserves tu consulta; no envía mensajes ni confirma pedidos.</p></div></aside><form id="contact-form"><div class="form-row"><div><label for="name">Tu nombre</label><input id="name" name="nombre" autocomplete="name" maxlength="100" required placeholder="¿Cómo te llamas?"></div><div><label for="email">Correo electrónico</label><input id="email" name="correo" type="email" autocomplete="email" maxlength="180" required placeholder="tu@correo.com"></div></div><label for="subject">¿Sobre qué quieres preguntar?</label><input id="subject" name="asunto" required maxlength="160" placeholder="Bebidas, ingredientes, disponibilidad…"><label for="message">Tu mensaje</label><textarea id="message" name="mensaje" required minlength="10" maxlength="3000" rows="5" placeholder="Cuéntanos un poco más (mínimo 10 caracteres)"></textarea><p class="privacy-note">Tus datos se procesan únicamente en este navegador y no se guardan en un servidor.</p><button class="button" type="submit" id="download-query" disabled>Descargar mi consulta <span aria-hidden="true">↓</span></button><p id="form-status" role="status"></p><noscript><p>Activa JavaScript para generar y descargar tu consulta.</p></noscript></form></section>''')
